package com.grandsigil.client;

import com.grandsigil.GrandSigil;
import java.lang.reflect.Field;
import java.util.Map;
import java.util.WeakHashMap;
import java.util.function.Function;
import net.minecraft.world.entity.Entity;
import software.bernie.geckolib.animatable.GeoEntity;
import software.bernie.geckolib.core.animation.AnimatableManager;
import software.bernie.geckolib.core.animation.AnimationController;

public final class GeckoStill {
    private static final Map<AnimationController<?>, Function<?, Double>> SAVED = new WeakHashMap();
    private static Field speedField;
    private static boolean failed;

    private GeckoStill() {
    }

    public static void freeze(Entity entity) {
        if (failed || !(entity instanceof GeoEntity)) {
            return;
        }
        GeoEntity geo = (GeoEntity)entity;
        try {
            AnimatableManager manager = geo.getAnimatableInstanceCache().getManagerForId((long)entity.m_19879_());
            if (manager == null) {
                return;
            }
            for (AnimationController controller : manager.getAnimationControllers().values()) {
                if (!SAVED.containsKey(controller)) {
                    SAVED.put(controller, GeckoStill.read(controller));
                }
                controller.setAnimationSpeed(0.0);
            }
        }
        catch (Throwable error) {
            failed = true;
            GrandSigil.LOGGER.warn("The Stilled World could not stop GeckoLib animation; those creatures will keep moving", error);
        }
    }

    public static void thaw(Entity entity) {
        if (failed || !(entity instanceof GeoEntity)) {
            return;
        }
        GeoEntity geo = (GeoEntity)entity;
        try {
            AnimatableManager manager = geo.getAnimatableInstanceCache().getManagerForId((long)entity.m_19879_());
            if (manager == null) {
                return;
            }
            for (AnimationController controller : manager.getAnimationControllers().values()) {
                Function<?, Double> saved = SAVED.remove(controller);
                if (saved != null) {
                    controller.setAnimationSpeedHandler(saved);
                    continue;
                }
                controller.setAnimationSpeed(1.0);
            }
        }
        catch (Throwable error) {
            failed = true;
        }
    }

    private static Function<?, Double> read(AnimationController<?> controller) {
        try {
            if (speedField == null) {
                speedField = AnimationController.class.getDeclaredField("animationSpeedModifier");
                speedField.setAccessible(true);
            }
            return (Function)speedField.get(controller);
        }
        catch (Throwable error) {
            return null;
        }
    }
}

